from typing import List

class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        if not grid or not grid[0]:
            return []
        m, n = len(grid), len(grid[0])
        result = []
        take = True  # flag to determine whether to take the current cell
        for i in range(m):
            if i % 2 == 0:  # left-to-right
                cols = range(n)
            else:  # right-to-left
                cols = range(n - 1, -1, -1)
            for j in cols:
                if take:
                    result.append(grid[i][j])
                take = not take
        return result
