class Solution:
    def minCost(self, nums):
        from functools import lru_cache
        n = len(nums)
        @lru_cache(None)
        def dfs(i):
            if i >= n:
                return 0
            remaining = n - i
            if remaining <= 2:
                return max(nums[i:]) if remaining else 0
            # option 1: remove i & i+1
            opt1 = max(nums[i], nums[i+1]) + dfs(i+2)
            # option 2: remove i & i+2
            opt2 = max(nums[i], nums[i+2]) + dfs(i+1)
            # option 3: remove i+1 & i+2
            opt3 = max(nums[i+1], nums[i+2]) + dfs(i)
            return min(opt1, opt2, opt3)
        return dfs(0)
